from datetime import datetime
import pytz
import re
from faker import Faker


_UTC_OFFSET_PATTERN = re.compile(r"^UTC([+-])([0-1]\d|2[0-3]):([0-5]\d)$")


def _parse_timezone(timezone_name):
    """
    Return a tuple of (timezone_label, tzinfo) for valid timezones.
    Supports pytz timezones and UTC±HH:MM fixed offsets.
    """
    if timezone_name in pytz.all_timezones:
        return timezone_name, pytz.timezone(timezone_name)

    match = _UTC_OFFSET_PATTERN.fullmatch(timezone_name)
    if match:
        sign, hours, minutes = match.groups()
        offset_minutes = int(hours) * 60 + int(minutes)
        if sign == "-":
            offset_minutes = -offset_minutes
        return timezone_name, pytz.FixedOffset(offset_minutes)

    return None, None


def task_func(epoch_milliseconds, seed=0, timezones=["UTC"]):
    fake = Faker()
    fake.seed_instance(seed)

    # Convert epoch milliseconds to the current system timezone.
    local_dt = datetime.fromtimestamp(epoch_milliseconds / 1000.0).astimezone()

    # Normalize input timezones.
    if timezones is None:
        requested_timezones = []
    elif isinstance(timezones, str):
        requested_timezones = [timezones]
    else:
        requested_timezones = list(timezones)

    valid_timezones = []
    for tz_name in requested_timezones:
        if tz_name is None:
            continue
        label, tzinfo = _parse_timezone(str(tz_name))
        if tzinfo is not None:
            valid_timezones.append((label, tzinfo))

    # Select timezone: UTC if none valid or none specified, otherwise randomly pick a valid one.
    if not valid_timezones:
        selected_label, selected_tz = "UTC", pytz.UTC
    else:
        selected_label, selected_tz = fake.random_element(valid_timezones)

    # Convert the local datetime to the selected timezone.
    event_dt = local_dt.astimezone(selected_tz)

    event_name = fake.catch_phrase()

    return {
        event_name: [
            {
                "date": event_dt.strftime("%Y-%m-%d"),
                "time": event_dt.strftime("%H:%M:%S"),
                "timezone": selected_label,
            }
        ]
    }
